using System;using System.Linq;using NUnit.Framework;using UnityEditor;using UnityEngine;using Rootborn.Game.Common;using Rootborn.Game.Localization;using Rootborn.Game.StudentLife;using Object=UnityEngine.Object;
namespace Rootborn.Tests.EditMode.UI.StudentLife{public sealed class OutsideSchoolPromptReadabilityTests{GameObject point;GameDataRegistry registry;string language;[SetUp]public void Setup(){language=GameText.Language;registry=AssetDatabase.LoadAssetAtPath<GameDataRegistry>("Assets/Data/Registry/GameDataRegistry.asset");GameDataRegistryProvider.SetOverrideForTests(registry);point=new GameObject("OutsidePromptFixture",typeof(OutsideSchoolActivityInteractor));}[TearDown]public void Cleanup(){Object.DestroyImmediate(point);GameText.Language=language;GameDataRegistryProvider.ClearOverrideForTests();}
[TestCase("ko","outside.self-study.library","[E] 도서관에서 독학")][TestCase("en","outside.self-study.library","[E] Study at the library")][TestCase("ko","outside.help-neighbor","[E] 이웃 돕기")][TestCase("en","outside.help-neighbor","[E] Help a neighbor")]public void AuthoredActivityUsesWholeLocalizedKeyWithoutChangingDefinition(string lang,string id,string expected){GameText.Language=lang;var a=registry.OutsideSchoolActivities.Single(x=>x!=null&&x.Id==id);var before=EditorJsonUtility.ToJson(a);var p=point.GetComponent<OutsideSchoolActivityInteractor>();p.Bind(a);Assert.That(p.InteractionPrompt,Is.EqualTo(expected));Assert.That(p.InteractionPrompt,Is.EqualTo(expected),"Repeated prompt rendering is read-only");Assert.That(EditorJsonUtility.ToJson(a),Is.EqualTo(before));Assert.That(p.Activity,Is.SameAs(a));}
[TestCase("ko","[E] 학교 밖 활동")][TestCase("en","[E] Outside-school activity")]public void MissingActivityHasFriendlyLocalizedFallback(string lang,string expected){GameText.Language=lang;Assert.That(point.GetComponent<OutsideSchoolActivityInteractor>().InteractionPrompt,Is.EqualTo(expected));}
[TestCase("ko","[E] 학교 밖 활동")][TestCase("en","[E] Outside-school activity")]public void UnknownTranslationDoesNotRevealTechnicalTail(string lang,string expected){GameText.Language=lang;var a=ScriptableObject.CreateInstance<OutsideSchoolActivityDefinition>();try{a.ConfigureForTests("fixture.outside.secret","fixture.outside.secret");point.GetComponent<OutsideSchoolActivityInteractor>().Bind(a);Assert.That(point.GetComponent<OutsideSchoolActivityInteractor>().InteractionPrompt,Is.EqualTo(expected));}finally{Object.DestroyImmediate(a);}}
[TestCase("ko","기초 학습")][TestCase("en","Basic Study")]public void StudyGrowthTargetUsesAuthoredLocalizedTitleWithoutChangingSkill(string lang,string expected){GameText.Language=lang;var skill=registry.StudentLifeSkills.Single(x=>x!=null&&x.Id=="skill.basic-study");string before=EditorJsonUtility.ToJson(skill);Assert.That(GameText.Get(skill.DisplayNameKey),Is.EqualTo(expected));Assert.That(EditorJsonUtility.ToJson(skill),Is.EqualTo(before));}
}}
